-- 06-4-rollback.sql — undo 06-3-apply.sql (generated by split_06.py; same logic as the rollback
-- section of 06-apply-rewrites.sql). Restores each rewritten field from the backup, but only where
-- the field still holds the text 06-3 wrote (later edits are left alone). Safe to run twice.
-- Run with psql -v ON_ERROR_STOP=1 -f <file>, or paste the whole file into the SQL editor (one call per file).

begin;

do $$
begin
  if to_regclass('audit_backup.rewrites_20261122_proposals') is null then
    raise exception 'Nothing to roll back: audit_backup.rewrites_20261122_proposals does not exist';
  end if;
end $$;

do $$
declare bad int;
begin
  if to_regclass('audit_backup.rewrites_20261122_destinations') is null
     or to_regclass('audit_backup.rewrites_20261122_translations') is null then
    raise exception 'Backup tables missing: nothing to roll back';
  end if;
  select count(*) into bad from pg_class c join pg_namespace s on s.oid = c.relnamespace
  where s.nspname = 'audit_backup'
    and c.relname in ('rewrites_20261122_proposals', 'rewrites_20261122_destinations', 'rewrites_20261122_translations')
    and not c.relrowsecurity;
  if bad > 0 then raise exception 'RLS is off on % audit_backup rewrite tables: backup incomplete', bad; end if;
  -- Every affected row that exists now must already be in the backup.
  select count(*) into bad from public.destinations d
  where d.slug in (select slug from audit_backup.rewrites_20261122_proposals where locale = 'en')
    and not exists (select 1 from audit_backup.rewrites_20261122_destinations b where b.id = d.id);
  if bad > 0 then raise exception '% affected destinations are not in the backup: backup incomplete', bad; end if;
  select count(*) into bad from public.content_translations t
  where t.entity_type = 'destination'
    and (t.locale, t.entity_id) in (select locale, slug from audit_backup.rewrites_20261122_proposals where locale <> 'en')
    and not exists (select 1 from audit_backup.rewrites_20261122_translations b where b.id = t.id);
  if bad > 0 then raise exception '% affected translations are not in the backup: backup incomplete', bad; end if;
end $$;


do $$
declare p record; n int; total int := 0;
begin
  if to_regclass('audit_backup.rewrites_20261122_proposals') is null then
    raise exception 'Nothing to roll back: audit_backup.rewrites_20261122_proposals does not exist';
  end if;
  for p in select * from audit_backup.rewrites_20261122_proposals loop
    if p.locale = 'en' and p.col = 'tagline' then
      update public.destinations d set tagline = b.tagline, updated_at = now()
        from audit_backup.rewrites_20261122_destinations b
       where b.id = d.id and d.slug = p.slug and d.tagline = p.new_text;
    elsif p.locale = 'en' and p.col = 'seo_description' then
      update public.destinations d set seo_description = b.seo_description, updated_at = now()
        from audit_backup.rewrites_20261122_destinations b
       where b.id = d.id and d.slug = p.slug and d.seo_description = p.new_text;
    elsif p.locale = 'en' then
      update public.destinations d set travel_plan = jsonb_set(d.travel_plan, p.path, b.travel_plan #> p.path, false),
                                       updated_at = now()
        from audit_backup.rewrites_20261122_destinations b
       where b.id = d.id and d.slug = p.slug and d.travel_plan #>> p.path = p.new_text;
    else
      update public.content_translations t set fields = jsonb_set(t.fields, p.path, b.fields #> p.path, false),
                                               updated_at = now()
        from audit_backup.rewrites_20261122_translations b
       where b.id = t.id and t.entity_type = 'destination' and t.entity_id = p.slug and t.locale = p.locale
         and t.fields #>> p.path = p.new_text;
    end if;
    get diagnostics n = row_count;
    total := total + n;
  end loop;
  raise notice 'Rollback restored % fields', total;
end $$;

commit;
